bool wordBreak(String s, Map<String, List<String>> wordDict) {
  if (s.isEmpty) return false;
  List<String> wordDictList = wordDict.values.toList();
  Set<String> wordSet = wordDictList.toSet();
  List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  return dp[s.length];
}

