void fn0() {

  List<String> wordDictionary = ['leet', 'code', 'dog', 'and', 'cat', 'pine', 'pen', 'applepen', 'leetcode', 'cats', 'catsandog', 'pineapple', 'applepenapple', 'leetcode', 'pineapplepenapple', 'leetcode', 'leetcode'];
  List<String> segmentStrings = ['leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode', 'leetcode'];

  int n = segmentStrings.length;

  List<int> dp = List.filled(n + 1, 0);

  Set<String> wordSet = wordDictionary.toSet();

  for (int i = 1; i <= n; i++) {
    List<Map<String, int>> memo = List.generate(i, (_) => {});

    List<int> bestLen = List.filled(i, 0);

    for (int j = 0; j < i; j++) {
      for (int k = 0; k < j; k++) {
        String sub = segmentStrings[k];
        String subPrefix = sub.substring(0, j - k);
        if (wordSet.contains(subPrefix)) {
          if (memo.containsKey(sub) && bestLen[k] < dp[j - k]) {
            bestLen[j] = dp[j - k];
          }
        }
      }
    }

    dp[i] = bestLen[i - 1] + 1;
  }

  print('=== Word Break (Can Segment?) ===');
  for (int i = 1; i <= n; i++) {
    if (dp[i] == 0) {
      print('String: "${segmentStrings[i - 1]}": Cannot segment');
    } else {
      print('String: "${segmentStrings[i - 1]}": Can segment');
    }
  }

  print('=== Minimum Word Breaks ===');
  for (int i = 1; i <= n; i++) {
    if (dp[i] == 0) {
      print('String: "${segmentStrings[i - 1]}": Minimum words needed: -1');
    } else {
      print('String: "${segmentStrings[i - 1]}": Minimum words needed: ${dp[i]}');
    }
  }

  print('=== Word Break II (All Segmentations) ===');
  for (int i = 1; i <= n; i++) {
    if (dp[i] == 0) continue;

    List<List<String>> segmentations = [];
    List<Map<String, int>> memo = {};

    void search(int start, List<String> path) {
      if (start == i) {
        segmentations.add(List.from(path));
        return;
      }

      for (int j = start; j < i; j++) {
        if (dp[j] + 1 <= dp[start] && memo.containsKey(segmentStrings[j])) {

          List<String> subPath = List.from(path);
          subPath.add(segmentStrings[j]);

          String sub = segmentStrings[j];
          String subPrefix = sub.substring(0, start - j);
          if (wordSet.contains(subPrefix)) {
            search(start, subPath);
          }
        }
      }
    }

    memo[segmentStrings[start]] = dp[start];
    search(start, []);

    for (var seg in segmentations) {
      print('All possible segmentations: ${seg.join(" ")}');
    }
  }
}

