bool isWordBreak(String word, Set<String> dictionary) {

  if (word.isEmpty) return false;
  List<bool> dp = List.filled(word.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && dictionary.contains(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[word.length];
}

int minWordBreak(String word, Set<String> dictionary) {

  if (word.isEmpty) return 0;
  List<int> dp = List.filled(word.length + 1, word.length + 1);
  dp[0] = 0; 

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] < word.length + 1 && dictionary.contains(word.substring(j, i))) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }
  return dp[word.length];
}

List<List<String>> wordBreak(String word, Set<String> dictionary) {

  if (word.isEmpty) return [];
  List<List<String>> dp = List.filled(word.length + 1, <String>[]);
  dp[0].add(""); 

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j].isNotEmpty && dictionary.contains(word.substring(j, i))) {
        for (var seg in dp[j]) {
          dp[i].add(seg + word[i - 1]);
        }
      }
    }
  }
  return dp[word.length];
}

