bool wordBreak(String s, List<String> wordDict) {
  if (s.isEmpty) return true;
  Set<String> wordSet = wordDict.toSet();
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

int minWordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List.filled(s.length + 1, s.length + 1);
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i))) {
        if (dp[j] + 1 < dp[i]) {
          dp[i] = dp[j] + 1;
        }
      }
    }
  }

  if (dp[s.length] == s.length + 1) return -1;
  return dp[s.length];
}

List<List<String>> wordBreak2(String s, List<String> wordDict) {
  if (s.isEmpty) return [];
  Set<String> wordSet = wordDict.toSet();
  List<List<String>> results = [];

  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  if (!dp[s.length]) return results;

  List<List<String>> segmentations = [];

  List<List<String>> backtrack(int start, int end) {
    if (start == end) {
      return [s.substring(start, end)];
    }

    List<List<String>> options = [];
    for (int i = start; i <= end; i++) {
      if (dp[i] && wordSet.contains(s.substring(i, end + 1))) {
        options.addAll(backtrack(start, i - 1));
      }
    }

    for (var seg in options) {
      seg.add(s.substring(start, end + 1));
      results.add(seg);
    }
    return options;
  }

  backtrack(0, s.length);
  return results;
}

