void fn0() {

  final String s = 'leetcode';
  final String d = 'leet';

  bool wordBreak(String s, String d) {
    if (s.isEmpty || d.isEmpty) return false;
    bool wordBreak(String s, String d, Map<String, bool> dp, Set<String> dict) {
      if (s.isEmpty) return true;
      if (dp.containsKey(s)) return dp[s]!;
      bool found = false;
      for (var word in dict) {
        if (s.startsWith(word) && wordBreak(s.substring(word.length), d, dp, dict)) {
          found = true;
          break;
        }
      }
      dp[s] = found;
      return found;
    }
    return wordBreak(s, d, {s: false}, d.split(' '));
  }

  Map<String, List<String>> allSegmentations(String s, String d) {
    if (s.isEmpty) return {};
    List<String> words = d.split(' ');
    Map<String, List<String>> segmentations = {};
    void search(String s, String word, List<String> prefix) {
      if (word.isEmpty) {
        if (s.isEmpty) {
          if (!segmentations.containsKey(prefix)) {
            segmentations[prefix] = [];
          }
          segmentations[prefix]!.add(s);
        }
        return;
      }
      if (!word.contains(s)) return;
      String sub = word.substring(0, s.length);
      if (sub == s) {
        if (s.isNotEmpty) {
          if (!segmentations.containsKey(prefix + word)) {
            segmentations[prefix + word] = [];
          }
          segmentations[prefix + word]!.add(s);
        }
      } else {
        List<String> rest = word.substring(s.length).split('');
        for (int i = 0; i < rest.length; i++) {
          String next = rest.join('');
          search(s, next, prefix + word[s.length]);
        }
      }
    }
    for (var word in words) {
      search(word, s, '');
    }
    return segmentations;
  }

  Map<String, int> minWords(String s, String d) {
    if (s.isEmpty || d.isEmpty) return {};
    List<String> words = d.split(' ');
    Map<String, int> dp = {};
    for (int i = 0; i <= s.length; i++) {
      dp[i] = s.length + 1;
    }
    dp[0] = 0;
    for (int i = 0; i < s.length; i++) {
      for (var word in words) {
        if (i >= word.length && s.substring(i, i + word.length) == word) {
          if (dp[i] == s.length + 1) {
            dp[i + word.length] = 1;
          } else if (dp[i + word.length] > dp[i] + 1) {
            dp[i + word.length] = dp[i] + 1;
          }
        }
      }
    }
    return dp;
  }

  print('=== Word Break (Can Segment?) ===');
  bool canSegment = wordBreak(s, d);
  print('Can segment: $canSegment'); 

  print('=== Minimum Word Breaks ===');
  Map<String, int> minWords = minWords(s, d);
  print('Minimum words needed: ${minWords[s.length]}'); 

  print('=== Word Break II (All Segmentations) ===');
  Map<String, List<String>> allSeg = allSegmentations(s, d);
  print('All possible segmentations:');
  for (var key in allSeg.keys) {
    print('  $key: ${allSeg[key]}');
  }
}

