Map<String, int> fn0(List<String> operations, int capacity) {
  List<int> stack = [0];
  List<String> history = [];
  List<List<int>> log = [];
  bool overflow = false;

  void printLog() {
    log.add([stack.length, history.join(' ')]);
  }

  void undo() {
    if (stack.length > 1) {
      stack.removeLast();
    } else {
      history.clear();
      log.clear();
    }
  }

  void add(int amount) {
    if (stack.length >= capacity) {
      overflow = true;
      return;
    }

    int newTotal = stack.last + amount;
    if (newTotal > capacity) {
      overflow = true;
      return;
    }

    stack.add(newTotal);
    history.add('ADD $amount');
    printLog();
  }

  void end() {
    if (stack.isEmpty) {
      overflow = true;
      return;
    }

    int total = stack.removeLast();
    history.add('END');
    printLog();
  }

  void begin() {
    if (stack.isEmpty) {
      overflow = true;
      return;
    }

    int sum = 0;
    while (stack.isNotEmpty && stack.last > 0) {
      sum += stack.removeLast();
    }

    stack.add(sum);
    history.add('BEGIN');
    printLog();
  }

  for (var op in operations) {
    if (op == 'BEGIN') {
      begin();
    } else if (op == 'END') {
      end();
    } else if (op == 'ADD') {
      int amount = int.parse(op.split(' ')[1]);
      add(amount);
    } else if (op == 'UNDO') {
      undo();
    }
  }

  return {
    'overflow': overflow,
    'total': stack.isEmpty ? 0 : stack.last,
    'history': history.length,
  };
}

