void fn0() {

  String text = """

  HERE IS A SIMPLE EXAMPLE

  The goal is to write a Dart program that searches a given text for
  a specified pattern (also provided as a string). The search is
  implemented using a divide-and-conquer approach on sublists
  of the text.

  The main method takes two arguments: the text and the pattern.
  It creates two lists: one that stores the characters of the text,
  and one that stores the characters of the pattern. Then it calls
  the search method on the sublists of the text.

  The search method uses a recursive divide-and-conquer approach.
  It first checks if the pattern is empty (in which case the position
  is immediately returned). Otherwise, it searches the sublist of the
  text starting at the current position and ending at the current position
  plus the length of the pattern. If the pattern is found, the position
  is returned. Otherwise, the sublist is divided into two halves, and
  the search is called recursively on each half.

  The main method prints the result: either "Pattern found at positions: <list>"
  if the pattern is found, or "Pattern not found." if not found.

  """;

  String pattern = "EXAMPLE";

  List<String> words = text.split(' ');
  List<String> pat = pattern.split('');

  List<int> charArr = List.filled(words.length, 0);
  for (int i = 0; i < words.length; i++) {
    charArr[i] = words[i].codeUnitAt(0);
  }

  List<int> patArr = List.filled(pat.length, 0);
  for (int i = 0; i < pat.length; i++) {
    patArr[i] = pat[i].codeUnitAt(0);
  }

  List<int> result = [];

  void search(List<int> subArr, List<int> patArr) {
    if (patArr.isEmpty) {
      result.add(0);
      return;
    }
    int i = 0;
    int j = 0;
    while (i < subArr.length && j < patArr.length) {
      if (subArr[i] == patArr[j]) {
        i++;
        j++;
      } else if (subArr[i] < patArr[j]) {
        i++;
      } else {
        j++;
      }
    }
    if (j == patArr.length) {
      result.add(i);
    } else {
      search(subArr.sublist(i), patArr.sublist(j));
      search(subArr.sublist(i + 1), patArr.sublist(j));
    }
  }

  search(charArr, patArr);

  if (result.isEmpty) {
    print("Pattern not found.");
  } else {
    print("Pattern found at positions: ${result.join(', ')}");
  }
}

