void fn0() {

  String text = '''

  HERE IS A SIMPLE EXAMPLE

  You can include line breaks,
  "special characters", and other types
  of escape characters without any issues.

  Feel free to customize it as needed.
  ''';

  String pattern = 'EXAMPLE';

  List<int> search(String text, String pattern) {
    List<int> result = [];
    int n = text.length;
    int m = pattern.length;

    if (m == 0) {
      for (int i = 0; i < n; i++) {
        result.add(i);
      }
      return result;
    }

    List<List<bool>> dp = List.generate(
      n + 1,
      (_) => List.filled(m + 1, false),
    );

    for (int i = 0; i <= n; i++) dp[i][0] = true;
    for (int j = 1; j <= m; j++) dp[0][j] = true;

    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= m; j++) {
        if (text[i - 1] == pattern[j - 1]) {
          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = dp[i - 1][j - 1] || dp[i - 1][j];
        }
      }
    }

    result.add(0); 
    for (int i = 1; i <= n - m + 1; i++) {
      if (dp[i][m]) {
        result.add(i);
      }
    }
    return result;
  }

  List<int> matches = search(text, pattern);

  if (matches.isEmpty) {
    print('Pattern not found.');
  } else {
    print('Pattern found at positions: ${matches.join(', ')}');
  }
}

