void fn0(List<String> args) {

  final String text = args.isNotEmpty ? args.join(' ') : 'HERE IS A SIMPLE EXAMPLE';

  int kthGrammar(int k, String pattern) {
    if (k < 1) {
      throw ArgumentError('Invalid k: $k');
    }

    List<int> dp = List<int>.filled(k + 1, 0);
    dp[0] = 1;

    for (int i = 0; i < text.length; i++) {

      List<int> nextDp = List<int>.filled(k + 1, 0);
      for (int j = 0; j <= k; j++) {
        for (int len = 1; len <= k && i + len <= text.length; len++) {
          String sub = text.substring(i, i + len);
          if (sub == pattern) {
            int oldVal = dp[j];
            int newVal = j < len ? oldVal + 1 : 1;
            nextDp[newVal] = nextDp[newVal]! + oldVal;
          }
        }
      }
      dp = nextDp;
    }

    int pos = 0;
    for (int v in dp) {
      if (v > 0) {
        pos++;
      }
    }
    return pos;
  }

  int k = args.isNotEmpty ? int.parse(args[0]) : 1;
  String pattern = args.isNotEmpty ? args[1] : 'EXAMPLE';

  final int result = kthGrammar(k, pattern);
  final String found = result == -1 ? 'Pattern not found.' : 'Pattern found at positions: ${result.join(', ')}';
  print(found);
}

