  int rows = requests.length;
  int cols = requests[0].length;

  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  for (int r = 0; r < rows; r++) {
    dp[r][0] = requests[r][0];
  }

  for (int c = 1; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      int prev = dp[r][c - 1];

      if (r > 0) {
        int up = dp[r - 1][c - 1];
        int down = dp[r + 1][c - 1];

        dp[r][c] = up > down ? up : down;
      } else {
        dp[r][c] = prev > 0 ? prev : requests[r][c];
      }
    }
  }

  int total = 0;

  for (int r = 0; r < rows; r++) {
    int rowMax = dp[r].reduce((a, b) => a > b ? a : b);
    total += rowMax;
  }

  return total;
}

