String fn0(List<int> minutes, int k) {
  if (minutes.isEmpty || k <= 0) {
    return "0:0";
  }
  int n = minutes.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int diff = minutes[i - 1] - minutes[i - 2];
    if (diff < 0) {
      diff = -diff;
    }
    dp[i] = dp[i - 1] + diff + 1;
  }
  int left = 0;
  int right = n;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (dp[mid] < k) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  int start = left;
  int end = n;
  if (start > 0) {
    int diff = minutes[start - 1] - minutes[start - 2];
    if (diff < 0) {
      diff = -diff;
    }
    end = start + (dp[start] - diff);
  }
  int total = end - start;
  int hours = total ~/ 60;
  int mins = total % 60;
  return "$hours:$mins";
}

