  for (int i = 0; i < k; i++) {
    current.add(items[i]);
  }

  print('Current combination: ${current.join(', ')}');

  while (true) {

    List<String> next = [];

    for (int i = k - 1; i >= 0; i--) {
      if (current[i] != items[i]) {
        next.add(current[i]);
      }
    }

    next.add(items[k - 1]);

    print('Next combination: ${next.join(', ')}');

    current = next;

