void fn0(List<String> args) {

  List<String> items = ['A', 'B', 'C', 'D'];

  String kStr = args.isNotEmpty ? args[0] : '3';
  int k = int.tryParse(kStr) ?? 3;

  if (k <= 0 || k > items.length) {
    print('k must be between 0 and n (inclusive). n=$items.length, k=$k');
    print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
    print('No args provided. Using default input: k=$k, items=$items');
    k = 3;
    items = ['A', 'B', 'C', 'D'];
  }

  List<List<String>> combinations = _generateCombinations(items, k);

  print('Total combinations: ${combinations.length}');
  print(combinations);
}

List<List<String>> _generateCombinations(List<String> items, int k) {
  if (items.isEmpty || k == 0) return [];

  List<List<String>> result = [];

  void backtrack(int start, List<String> current, List<String> remaining) {
    if (current.length == k) {
      result.add(List.from(current)); 
      return;
    }

    for (int i = start; i < items.length; i++) {
      String item = items[i];
      if (current.isEmpty || current.last != item) {
        current.add(item);
        remaining.remove(item);
        backtrack(i + 1, current, remaining);
        current.removeLast();
        remaining.add(item);
      }
    }
  }

  List<String> remaining = List.from(items);
  backtrack(0, [], remaining);
  return result;
}

