  bool unionFind(int a, int b) {
    if (find(a) == find(b)) return false;
    int x = find(a), y = find(b);
    if (x == y) return true;
    if (size[x] < size[y]) {
      int temp = x;
      x = y;
      y = temp;
    }
    size[x] += size[y];
    union[y] = x;
    return true;
  }

  int find(int x) {
