List<int> _dfs(Map<int, List<int>> graph, int start) {
  List<int> stack = [start];
  Set<int> visited = {};
  visited.add(start);
  List<int> traversal = [];

  while (stack.isNotEmpty) {
    int v = stack.removeLast();
    traversal.add(v);
    for (int neighbor in graph[v]!) {
      if (!visited.contains(neighbor)) {
        stack.add(neighbor);
        visited.add(neighbor);
      }
    }
  }

  return traversal;
}

List<int> _iterative(Map<int, List<int>> graph, int start) {
  List<int> queue = [start];
  Set<int> visited = {};
  visited.add(start);
  List<int> traversal = [];

  while (queue.isNotEmpty) {
    int v = queue.removeAt(0);
    traversal.add(v);
    for (int neighbor in graph[v]!) {
      if (!visited.contains(neighbor)) {
        queue.add(neighbor);
        visited.add(neighbor);
      }
    }
  }

  return traversal;
}

void _traverse(List<int> traversal, int node, String prefix) {
  print('Node $node -> $prefix');
  for (int neighbor in graph[node]!) {
    _traverse(traversal, neighbor, prefix + '  ');
  }
}

bool isReachable(Map<int, List<int>> graph, int u, int v) {
  Set<int> visited = {};
  List<int> queue = [u];
  visited.add(u);

  while (queue.isNotEmpty) {
    int u = queue.removeAt(0);
    if (u == v) {
      return true;
    }
    for (int neighbor in graph[u]!) {
      if (!visited.contains(neighbor)) {
        queue.add(neighbor);
        visited.add(neighbor);
      }
    }
  }

  return false;
}

