List<String> fn0(List<String> inventory, List<int> values) {
  Set<String> visited = {};
  Set<int> conflicts = {};
  List<List<String>> items = [];
  List<List<int>> weights = [];

  for (int i = 0; i < inventory.length; i++) {
    String item = inventory[i];
    int value = values[i];

    if (visited.contains(item)) {
      if (!conflicts.contains(value)) {
        conflicts.add(value);
      }
    } else {
      visited.add(item);
      items.add([item, value]);
      weights.add([value, i]);
    }
  }

  if (conflicts.isEmpty) {
    items.sort((a, b) {
      int byWeight = a[0].compareTo(b[0]);
      if (byWeight != 0) return byWeight;
      return a[1].compareTo(b[1]);
    });
    return items;
  }

  int n = items.length;
  List<List<int>> intervals = List.generate(n, (_) => [0, 0]);

  for (int i = 0; i < n; i++) {
    intervals[i] = [weights[i][0], i + 1];
  }

  int m = conflicts.length;
  List<List<int>> conflictIntervals = List.generate(m, (_) => [0, 0]);

  for (int i = 0; i < m; i++) {
    int v = conflicts[i];
    for (int j = 0; j < n; j++) {
      if (intervals[j][0] <= v && v < intervals[j][1]) {
        conflictIntervals[i] = [conflictIntervals[i][0] < intervals[j][0]
            ? conflictIntervals[i][0]
            : intervals[j][0],
            conflictIntervals[i][1] > intervals[j][1]
                ? conflictIntervals[i][1]
                : intervals[j][1]];
        break;
      }
    }
  }

  int left = 0;
  int right = n - 1;
  int answer = 0;

  while (left <= right) {
    int mid = (left + right) >> 1;

    int m1 = 0;
    int m2 = 0;

    for (int i = 0; i <= mid; i++) {
      int l1 = intervals[i][0];
      int r1 = intervals[i][1];

      for (int j = 0; j <= m; j++) {
        int l2 = conflictIntervals[j][0];
        int r2 = conflictIntervals[j][1];

        if (l2 <= l1 && r2 >= r1) {
          m1++;
          break;
        }
      }
    }

    int m3 = m;
    for (int i = mid + 1; i < n; i++) {
      int l4 = intervals[i][0];
      int r4 = intervals[i][1];

      for (int j = 0; j <= m; j++) {
        int l5 = conflictIntervals[j][0];
        int r5 = conflictIntervals[j][1];

        if (l5 <= l4 && r5 >= r4) {
          m3--;
          break;
        }
      }
    }

    if (m1 >= m2 && m1 >= m3) {
      answer = mid + 1;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return [answer, n - answer];
}

