  if (queue.isEmpty) return result;
  List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  while (queue.isNotEmpty) {
    List<String> top = queue.removeAt(0);
    String song = top[0];
    List<int> cross = top[1];
    for (List<int> dir in dirs) {
