  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.random() : this(
        (2 * (Math.random() * 2 - 1)).toDouble(),
        (2 * (Math.random() * 2 - 1)).toDouble(),
        (2 * (Math.random() * 2 - 1)).toDouble(),
        (Math.random() * 2 - 1).toDouble(),
      );

  const Quaternion.fromList(List<double> parts)
      : x = parts[0],
        y = parts[1],
        z = parts[2],
        w = parts[3];

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *=(double scalar) {
    x *= scalar;
    y *= scalar;
    z *= scalar;
    w *= scalar;
    return this;
  }

  Quaternion operator *(Quaternion other) =>
      Quaternion(x * other.w - other.x * w,
          y * other.w - other.y * w,
          z * other.w - other.z * w,
          w * other.w - x * other.x - y * other.y - z * other.z);

  Quaternion operator -() =>
      Quaternion(-x, -y, -z, -w);

  Quaternion operator ^(double angle) {
    double sin = angle * 0.5;
    return Quaternion(
        x * sin + Math.sqrt(1 - sin * sin) * z,
        y * sin + Math.sqrt(1 - sin * sin) * z,
        z * sin + Math.sqrt(1 - sin * sin) * x,
        w * sin + Math.sqrt(1 - sin * sin) * y);
  }

  Quaternion conjugate() =>
      Quaternion(x, y, z, -w);

  double norm() => Math.sqrt(x * x + y * y + z * z + w * w);

  Quaternion normalize() {
    final double inv = 1 / norm();
    return *this * inv;
  }

  Quaternion inverse() => conjugate() * norm().isZero ? zero() : conjugate() * norm();

  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

