      : norm = 1,
        realPart[0] = realPart[0] / norm,
        imaginaryPart[0] = imaginaryPart[0] / norm,
        realPart[1] = realPart[1] / norm,
        imaginaryPart[1] = imaginaryPart[1] / norm;

