class Quaternion {
  double x, y, z, w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  double conjugate() {
    return x * x - y * y - z * z + w * w;
  }

  Quaternion inverse() {
    double n = norm();
    if (n == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion normalized() {
    double n = norm();
    if (n == 0.0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion operator * (Quaternion other) {
    double xx = x * x, xy = x * y, xz = x * z, xw = x * w;
    double yy = y * y, yz = y * z, yw = y * w;
    double zz = z * z, zw = z * w;
    return Quaternion(
      xx * other.w + xy * other.z + xz * other.y + xw * other.w,
      yy * other.w + yz * other.z + yw * other.x + yy * other.w,
      zz * other.w + zw * other.y + zw * other.x + zz * other.w,
      xy * other.y + xz * other.y + yw * other.x + zw * other.z,
    );
  }

  @override
  String toString() {
    return 'q1 = $x + $y i + $z j + $w k';
  }

  @override
  int get hashCode() {
    int hash = x.hashCode;
    hash = 31 * hash + y.hashCode;
    hash = 31 * hash + z.hashCode;
    hash = 31 * hash + w.hashCode;
    return hash;
  }

  @override
  bool operator ==(covariant Quaternion other) {
    return x == other.x &&
        y == other.y &&
        z == other.z &&
        w == other.w;
  }

  Quaternion rotate(Quaternion axis, double angle) {
    double s = sin(angle);
    double c = cos(angle);
    double ax = axis.x, ay = axis.y, az = axis.z;
    return Quaternion(
      c * x + s * (ax * y - az * z),
      c * y + s * (ay * x - az * w),
      c * z + s * (ax * w - ay * x),
      c * w + s * (ax * z - ay * y),
    );
  }
}

