    return '($x, $y, $z, $w)';
  }

  Quaternion operator +(other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(other) {
    double rx = x * other.x - y * other.y - z * other.z - w * other.w;
    double ry = x * other.y + y * other.x + z * other.w - w * other.z;
    double rz = x * other.z + y * other.w + z * other.x - w * other.y;
    double rw = x * other.w + y * z + z * y + w * x;
    return Quaternion(rx, ry, rz, rw);
  }

  Quaternion operator ^(int n) {
    Quaternion acc = Quaternion(0.0, 0.0, 0.0, 0.0);
    Quaternion current = this;
    for (int i = 0; i < n; i++) {
      if (current.w.isEven) {
        acc += current;
      } else {
        acc -= current;
      }
      current *= current;
    }
    return acc;
  }

  Quaternion inverse() {
    if (w == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(-x / w, -y / w, -z / w, 1.0 / w);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  Quaternion normalize() {
    double norm = norm();
    if (norm == 0.0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  static Quaternion fromAxisAngle(List<double> axis, double angle) {
    double x = axis[0], y = axis[1], z = axis[2];
    double c = cos(angle / 2.0);
    double s = sin(angle / 2.0);
    return Quaternion(2.0 * x * y * c + 2.0 * z * s, 2.0 * x * z * c + 2.0 * y * s, 2.0 * y * z * c - 2.0 * x * s, c * c - s * s);
  }
}

