  int opposite = oppositeDirection & maskBits;
  int clearNorth = allExceptNorth & maskBits;

  int west = ((mask << 1) | (mask >> 7)) & maskBits;
  int north = ((mask >> 1) | (mask << 7)) & maskBits;
  int east = ((mask >> 2) | (mask << 6)) & maskBits;
  int south = ((mask >> 3) | (mask << 5)) & maskBits;

