    signal |= (good << ((i * 2) + 1)) & maskBits;
    signal |= (fair << ((i * 2) + 2)) & maskBits;
    signal |= (poor << ((i * 2) + 3)) & maskBits;
  }

  int masked = signal & allDirections;
  int count = 0;
  while (masked != 0) {
    count++;
    masked &= masked - 1;
  }

