    int sum = 0;
    for (int i = start; i < end; i++) sum += durations[i];
    return sum.toDouble() / (end - start);
  }
  double left = calculate(0, durations.length);
  double right = calculate(0, durations.length);
  double minLeft = left < right ? left : right;
  double maxLeft = left < right ? right : left;
