int fn0(List<int> rolls) {
  int n = rolls.length;
  if (n == 0) return 0;
  if (n == 1) return rolls[0];

  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int best = 0;
    int current = 0;
    int j = i - 1;
    while (j >= 0) {
      int roll = rolls[j];
      current = current * 6 + roll;
      if (roll == 6) {
        best = current;
      } else if (roll == 1) {
        break;
      }
      j--;
    }
    dp[i] = best;
  }

  Map<int, int> counts = <int, int>{};
  for (int i = n; i >= 1; i--) {
    int value = dp[i];
    counts[value] = (counts[value] ?? 0) + 1;
  }

  int maxCount = 0;
  int maxFace = 0;
  for (int face = 1; face <= 6; face++) {
    int count = counts[face] ?? 0;
    if (count > maxCount ||
        (count == maxCount && face > maxFace)) {
      maxCount = count;
      maxFace = face;
    }
  }
  return maxFace;
}

