Map<String, int> fn0(List<List<String>> grid) {
  int rows = grid.length;
  if (rows == 0) return {};
  int cols = grid[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List<int>.filled(cols, 0));
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      String cell = grid[i][j];
      if (cell == ' ') continue;
      int up = (i > 0) ? dp[i - 1][j] : 0;
      int left = (j > 0) ? dp[i][j - 1] : 0;
      if (cell == '^' || cell == '|') {
        dp[i][j] = up > left ? up : left;
      } else {
        dp[i][j] = up > left ? left : up;
      }
    }
  }
  Map<String, int> result = {};
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      String cell = grid[i][j];
      if (cell == ' ') continue;
      int maxLen = dp[i][j];
      int left = 0;
      int right = 0;
      if (cell == '^' || cell == '|') {
        left = j - 1;
        right = j + 1;
      } else {
        left = j;
        right = j;
      }
      for (int k = left; k < right; k++) {
        String leftCell = grid[i][k];
        if (leftCell != ' ') break;
        left = k + 1;
      }
      for (int m = right; m < cols; m++) {
        String rightCell = grid[i][m];
        if (rightCell != ' ') break;
        right = m - 1;
      }
      int windowLen = right - left + 1;
      if (maxLen == 0) continue;
      result[cell] = (result[cell] ?? 0) + windowLen;
    }
  }
  return result;
}

