    'charlie': ['editor', 'admin'],
  };

  Map<String, List<String>> getCurrentRoleFor(String username) {
    if (!userRoles.containsKey(username)) return [];
    return userRoles[username]!;
  }

  void grantAccess(String username, String resource, String action) {
    List<String> role = getCurrentRoleFor(username);
    if (role.isEmpty) {
      print('  ⚠ User "$username" not found');
      return;
    }

    Map<String, List<String>> accessMap = permissions[resource]!;
    if (accessMap.isEmpty) {
      print('  ⚠ Resource "$resource" not found');
      return;
    }

    bool hasPermission = false;
    for (String role in role) {
      if (accessMap.containsKey(role)) {
        hasPermission = true;
        break;
      }
    }

    if (!hasPermission) {
      print('  ⚠ Access DENIED (Insufficient permissions)');
      return;
    }

    for (String role in role) {
      String key = '$role:$action';
      if (!accessMap[role]!.contains(key)) {
        accessMap[role]!.add(key);
      }
