void fn0() {

  const userRoles = {
    'user': ['read', 'write', 'delete', 'manage'],
    'editor': ['read', 'write', 'delete'],
    'moderator': ['read', 'write', 'delete', 'content_moderation'],
    'admin': ['read', 'write', 'delete', 'admin'],
  };

  const resources = {
    'document1': ['read', 'write', 'delete'],
    'document2': ['read', 'write', 'delete', 'sensitive_data'],
    'admin_resource': ['read', 'write', 'delete', 'admin'],
  };

  const actions = {
    'read': ['view', 'edit', 'remove'],
    'write': ['create', 'edit', 'remove'],
    'delete': ['delete', 'manage'],
    'admin': ['manage', 'remove'],
  };

  const roles = {
    'user': ['user', 'editor', 'moderator', 'admin'],
    'editor': ['editor'],
    'moderator': ['moderator'],
    'admin': ['admin'],
  };

  const userHierarchy = {
    'user': ['editor', 'moderator', 'admin'],
    'editor': ['moderator', 'admin'],
    'moderator': ['admin'],
    'admin': [],
  };

  const auditLog = {
    'alice': ['2024-01-01 10:00:00', 'read', 'document1', 'SUCCESS'],
    'bob': ['2024-01-01 10:05:00', 'write', 'document2', 'SUCCESS'],
    'charlie': ['2024-01-01 10:10:00', 'delete', 'document1', 'SUCCESS'],
    'diana': ['2024-01-01 10:15:00', 'read', 'admin_resource', 'DENIED'],
  };

  String? getUserRole(String username) {
    for (var role in roles.keys) {
      if (roles[role]!.contains(username)) {
        return role;
      }
    }
    return null;
  }

  Map<String, List<String>> permissionsFor(String role) {
    return userRoles[role]!;
  }

  Map<String, List<String>> inheritFrom(String baseRole) {
    return userHierarchy[baseRole]!;
  }

  Map<String, int> accessMatrixFor(String role, String resource) {
    var permissions = permissionsFor(role);
    var matrix = <String, String>{};
    for (var action in actions.keys) {
      if (permissions.contains(action)) {
        matrix[action] = (matrix[action] ?? '') + ' ' + resource;
      }
    }
    return matrix;
  }

  Map<String, List<String>> accessRequests = {
    'alice': ['read', 'document1'],
    'bob': ['write', 'document2'],
    'charlie': ['delete', 'document1'],
    'diana': ['read', 'admin_resource'],
  };

  void checkAccess(String username, String resource, String action) {
    var role = getUserRole(username);
    if (role != null) {
      var matrix = accessMatrixFor(role, resource);
      var allowedActions = actions[action]!;
      if (matrix.containsKey(action)) {
        print('  ➜ Access GRANTED (Role: $role) -> ${matrix[action]}');
      } else {
        print('  ➜ Access DENIED (Insufficient permissions)');
      }
    } else {
      print('  ➜ User "$username" not found');
    }
  }

  void grantAccess(String username, String resource, String action) {
    var role = getUserRole(username);
    if (role != null) {
      var newPermissions = permissionsFor(role) + [action];
      userRoles[role] = newPermissions;
      print('New role for $username: ${userRoles[role]}');
    } else {
      print('  ➜ User "$username" not found');
    }
  }

  void audit(String username, String resource, String action, String status) {
    var entry = '${username} ${action} $resource -> $status';
    print('➜ Audit Log: $entry');
    auditLog[username] = (auditLog[username] ?? <String>[])
        .add('${timestamp()} ${action} $resource $status');
  }

  void elevate(String username, String role) {
    var current = getUserRole(username);
    if (current != null) {
      var newPermissions = permissionsFor(current) + [role];
      userRoles[current] = newPermissions;
      print('Elevated $username from $current to $role');
    } else {
      print('  ➜ User "$username" not found');
    }
  }

  void denyAccess(String username, String resource, String action) {
    var role = getUserRole(username);
    if (role != null) {
      var permissions = permissionsFor(role);
      if (permissions.contains(action)) {
        permissions.remove(action);
        userRoles[role] = permissions;
        print('  ➜ Access denied');
      } else {
        print('  ➜ Permission "${action}" not found');
      }
    } else {
      print('  ➜ User "$username" not found');
    }
  }

  void displayRoles() {
    print('=== Role-Based Access Control System ===\n');
    for (var role in roles.keys) {
      var permissions = userRoles[role]!;
      var description = permissions.join(', ');
      print('Role: $role -> $description');
    }
  }

  void displayPermissions(String role) {
    var permissions = permissionsFor(role);
    print('Permissions: ${permissions.join(', ')}');
  }

  void displayHierarchy(String baseRole) {
    var hierarchy = inheritFrom(baseRole);
    print('Role Hierarchy:');
    for (var role in hierarchy.keys) {
      print('  ${role.padRight(8)} -> ${hierarchy[role]}');
    }
  }

  void displayMatrix(String role, String resource) {
    var matrix = accessMatrixFor(role, resource);
    print('User/Resource Access Matrix:');
    for (var action in actions.keys) {
      if (matrix.containsKey(action)) {
        print('  ${action.padRight(8)} -> ${matrix[action]}');
      }
    }
  }

  void displayAudit() {
    print('\n--- Audit Log ---\n');
    for (var username in auditLog.keys) {
      var actions = auditLog[username]!;
      print('User: $username');
      for (var action in actions) {
        var parts = action.split(' -> ');
        var resource = parts[0];
        var status = parts[1];
        print('  ➜ ${status} ${resource.padRight(8)}');
      }
    }
  }

  void printRecentAccessAttempts() {
    print('\nRecent Access Attempts:');
    for (var username in accessRequests.keys) {
      var actions = accessRequests[username]!;
      var resource = actions[0];
      var action = actions[1];
      print('  ➜ $username attempts to $action $resource');
    }
  }

  void displaySummary() {
    print('\n=== System Summary ===\n');
    var rolesCount = 0;
    var usersCount = 0;
    var resourcesCount = 0;
    var permissionsCount = 0;
    for (var role in roles.keys) {
      var permissions = permissionsFor(role);
      rolesCount++;
      usersCount += permissions.length;
      for (var p in permissions) {
        resourcesCount += p.length;
        permissionsCount += 1;
      }
    }
    print('Total Roles: $rolesCount');
    print('Total Users: $usersCount');
    print('Total Resources: $resourcesCount');
    print('Total Permissions: $permissionsCount');
  }

  void displayUserDetails(String username) {
    var role = getUserRole(username);
    if (role != null) {
      var permissions = permissionsFor(role);
      print('User: $username (${role.padRight(8)})');
      print('Permissions: ${permissions.join(', ')}');
    } else {
      print('  ➜ User "$username" not found');
    }
  }

  void displayPermissionElevation() {
    var rolesWithAdmin = {
      for (var role in roles.keys)
        if (roles[role]!.contains('admin')) role: 'admin'
    };
    print('\n--- Permission Elevation Scenario ---\n');
    for (var role in rolesWithAdmin) {
      var newRole = role.key;
      var newPermissions = role.value + ['delete', 'manage'];
      userRoles[newRole] = newPermissions;
      print('New role for ${role.key}: ${role.value}');
    }
  }

  print('=== Role-Based Access Control System ===\n');
  displayRoles();
  displayHierarchy('user');
  displayMatrix('editor', 'document1');
  displayAudit();

  var accessTests = [
    ['alice', 'read', 'document1'],
    ['bob', 'write', 'document2'],
    ['charlie', 'delete', 'document1'],
    ['diana', 'read', 'admin_resource'],
  ];
  print('\n--- Access Control Tests ---\n');
  for (var test in accessTests) {
    var username = test[0];
    var action = test[1];
    var resource = test[2];
    checkAccess(username, resource, action);
  }

  grantAccess('editor', 'document1', 'write');
  displayPermissions('editor');
  checkAccess('editor', 'document1', 'write');

  denyAccess('diana', 'admin_resource', 'read');
  displayMatrix('moderator', 'admin_resource');
  checkAccess('moderator', 'admin_resource', 'read');

  displayPermissions('admin');
  displayHierarchy('admin');
  displayMatrix('admin', 'admin_resource');

  printRecentAccessAttempts();

  elevate('charlie', 'admin');
  displayUserDetails('charlie');
  displayMatrix('admin', 'admin_resource');

