  void grantPermission(String role, String resource, List<String> actions) {
    if (!resourceAccess.containsKey(resource)) {
      resourceAccess[resource] = {};
    }
    for (var action in actions) {
      if (resourceAccess[resource]!.containsKey(action)) {
        resourceAccess[resource]![action] =
            (resourceAccess[resource]![action]! & role) | role;
      } else {
        resourceAccess[resource]![action] = role;
      }
    }
  }

  void denyPermission(String role, String resource, List<String> actions) {
    if (!resourceAccess.containsKey(resource)) {
