  int swap16(int value) {
    int temp = value & 0xFFFF;
    temp = (temp >> 16) | ((temp & 0xFFFF) << 16);
    return value & 0xFFFF;
  }

  int swap32(int value) {
    int temp = value & 0xFFFFFFFF;
    temp = (temp >> 32) | ((temp & 0xFFFFFFFF) << 32);
    return value & 0xFFFFFFFF;
