    int bytes = value & 0xFFFFFFFF;
    return bytes;
  }

  int littleEndian(int value) {
    int bytes = value & 0xFFFFFFFF;
    bytes = ((bytes >> 16) & 0xFF) | (bytes << 16);
    bytes = ((bytes >> 8) & 0xFF) | (bytes << 8);
    bytes = bytes & 0xFF;
