    int mask = bytes & 0x000000FF;
    if (mask == 0x000000FF) {
      return 0;
    }
    mask = bytes & 0x0000FFFF;
    if (mask == 0x0000FFFF) {
      return 1;
    }
    mask = bytes & 0x00FF00FF;
    if (mask == 0x00FF00FF) {
      return 2;
    }
    return 3; 
