  }

  void byteOrderExample() {

    String hostOrder = isLittleEndian ? 'Little Endian' : 'Big Endian';
    print('System is $hostOrder');

    int hostValue = 0x12345678;
    List<int> bytesHost = hostValue.toRadixString(16).padLeft(8, '0').codeUnits.toList();

    int networkValue = hostOrder == 'Little Endian'
        ? 0x78563412
        : 0x12345678;

    List<int> bytesNetwork = networkValue.toRadixString(16).padLeft(8, '0').codeUnits.toList();

    print('Host bytes: ${bytesHost.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');
    print('Network bytes: ${bytesNetwork.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}');

    int backToHost = hostOrder == 'Little Endian'
        ? bytesNetwork[0] * 0x100 + bytesNetwork[1]
        : bytesNetwork[3] * 0x100 + bytesNetwork[2];

    print('Back to host: $hostValue → ${backToHost.toRadixString(16).toUpperCase().padLeft(8, '0')}');

