    print('Original value: 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}');

    int swapped = value.swap16();
    print('Swap back: 0x${swapped.toRadixString(16).toUpperCase().padLeft(8, '0')}');

    value = 0x12345678;
    int swapped32 = value.swap32();
    print('Swap back: 0x${swapped32.toRadixString(16).toUpperCase().padLeft(8, '0')}');

    int bigEndian = 0x12345678;
    int bigSwapped = bigEndian.swap32();
    print('32-bit swap of 0x${bigEndian.toRadixString(16).toUpperCase().padLeft(8, '0')} -> 0x${bigSwapped.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  }

  void floatEndianness() {

