    String bigStr = value.toRadixString(16).padLeft(8, '0').split('').reversed.join();

    print('Float value: $value');
    print('As Little Endian: $littleStr → 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}');
    print('As Big Endian: $bigStr → 0x${value.toRadixString(16).toUpperCase().padLeft(8, '0')}');
  }

  void arrayEndianness() {

    List<int> values = [10, 20, 30, 40];
    print('Original 16-bit values: ${values.map((v) => v.toRadixString(16).toUpperCase().padLeft(4, '0')).join(' ')}');

    List<int> swapped = values.map((v) => v.toRadixString(16).toUpperCase().padLeft(4, '0')).toList();
    print('Swapped values: ${swapped.map((v) => v.padLeft(4, '0')).join(' ')}');

    int arrValue = 0x12345678;
    List<int> arrBytes = arrValue.toRadixString(16).padLeft(8, '0').codeUnits.toList();
    print('To bytes: [${arrBytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}]');

    int bytesValue = 0x08030210;
    List<int> reconstructed = [
