    ];
    print('From bytes: 0x${bytesValue.toRadixString(16).toUpperCase().padLeft(8, '0')} → [${reconstructed.map((b) => b.toRadixString(16).padLeft(2, '0')).join(' ')}]');

    int intArr = 0x12345678;
    int arrLE = isLittleEndian ? intArr : intArr.swap32();
    print('As Little Endian bytes: ${arrLE.toRadixString(16).toUpperCase().padLeft(8, '0')}');
