class Rectangle {
  final double width, height;
  final double x, y;

  Rectangle(this.width, this.height, [this.x = 0, this.y = 0]);

  Rectangle.origin(this.width, this.height)
      : this(width, height, 0, 0);

  Rectangle.unit()
      : this(1, 1);

  Rectangle.originUnit()
      : this(1, 1, 0, 0);

  Rectangle.originSize(double sx, double sy)
      : this(sx, sy, 0, 0);

  Rectangle.unitSize(double sx, double sy)
      : this(sx, sy, 0, 0);

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';

  Rectangle.origin(double w, double h)
      : width = w, height = h, x = 0, y = 0;

  Rectangle.originSize(double w, double h, double x, double y)
      : width = w, height = h, this.x = x, this.y = y;

  Rectangle.unit()
      : this(1, 1);

  Rectangle.unitSize(double w, double h, double x, double y)
      : this(w, h, x, y);

  Rectangle.unitOrigin()
      : this(1, 1, 0, 0);

  Rectangle.originUnit()
      : this(1, 1, 0, 0);

  Rectangle.point(Point p1, Point p2)
      : this(p2.x - p1.x, p2.y - p1.y);

  Rectangle.diagonal(Point p1, Point p2)
      : this(p1.x + p2.x, p1.y + p2.y);

  Rectangle.diagonalUnit()
      : this(2, 2);

  Rectangle.diagonalOrigin()
      : this(2, 2, 0, 0);

  Rectangle.circular(double radius)
      : this(2 * radius, 2 * radius);

  Rectangle.circularOrigin(double radius)
      : this(2 * radius, 2 * radius, 0, 0);

  double get area => width * height;

  bool contains(Point p) {
    return x <= p.x + p.x &&
        p.x <= x + width &&
        y <= p.y + p.y &&
        p.y <= y + height;
  }

  bool intersects(Rectangle other) {
    return (other.x < x + width && x < other.x + other.width) &&
        (other.y < y + height && y < other.y + other.height);
  }

  Rectangle union(Rectangle other) {
    double left = x < other.x ? x : other.x;
    double right = x + width < other.x + other.width ? x + width : other.x + other.width;
    double bottom = y < other.y ? y : other.y;
    double top = y + height < other.y + other.height ? y + height : other.y + other.height;
    return Rectangle(right - left, top - bottom);
  }

  Rectangle translate(double dx, double dy) {
    return Rectangle(width, height, x + dx, y + dy);
  }

  Rectangle scale(double sx, double sy) {
    return Rectangle(sx * width, sy * height, x, y);
  }

  Rectangle rotate(double angle) {
    double sin = sin(angle), cos = cos(angle);
    double newX = (x * cos - y * sin) + (width * cos / 2),
        newY = (x * sin + y * cos) + (height * sin / 2);
    return Rectangle(width, height, newX, newY);
  }

  Rectangle mirror(String axis) {
    double sign = 1;
    if (axis == 'y') {
      sign = -1;
    } else if (axis == 'x') {
      sign = 2;
    }
    return Rectangle(width, height, x + sign * width, y + sign * height);
  }

  Rectangle clipping(Rectangle clip) {
    double sx = x > clip.x ? x : clip.x,
        sy = y > clip.y ? y : clip.y,
        dx = x + width < clip.x + clip.width ? x + width : clip.x + clip.width,
        dy = y + height < clip.y + clip.height ? y + height : clip.y + clip.height;
    return Rectangle(dx - sx, dy - sy);
  }
}

