double eval(String formula, double G, double M, double R) {
  if (formula.isEmpty) return 0.0;
  if (formula == '0') return 0.0;

  List<String> terms = formula.split(' ');
  double value = eval(terms[0], G, M, R);
  for (int i = 1; i < terms.length; i++) {
    String op = terms[i];
    if (op == '*') {
      value *= eval(terms[i + 1], G, M, R);
    } else if (op == '+') {
      value += eval(terms[i + 1], G, M, R);
    }
  }
  return value;
}

