    for (int i = 0; i < c.length; i++) {
      sum += pow(c[i] - p[i], 2);
    }
    return sqrt(sum);
  }

  List<List<double>> clusterAssignments = List.generate(
    points.length,
    (_) => List<double>.filled(k, 0),
  );

  List<List<double>> centroids = List.generate(
    k,
    (_) => List<double>.generate(points[0].length, (_) => rand.nextDouble() * 10 - 5),
  );

  double tolerance = 0.001;

  int iterations = 0;
  bool converged = false;

  while (iterations < 1000 && !converged) {

