    for (int i = 0; i < points.length; i++) {
      double minDist = double.infinity;
      int bestCluster = -1;
      for (int c = 0; c < k; c++) {
        double distC = centroidDist(centroids[c], points[i]);
        if (distC < minDist) {
          minDist = distC;
          bestCluster = c;
        }
      }
      clusterAssignments[i][bestCluster] = 1;

      double newCentroid = 0;
      for (int j = 0; j < points[i].length; j++) {
        newCentroid += points[i][j];
      }
      newCentroid = newCentroid / points[i].length;
