    }

    for (int c = 0; c < k; c++) {
      for (int i = 0; i < points.length; i++) {
        if (clusterAssignments[i][c] == 1) {
          double distToNew = centroidDist(centroids[c], points[i]);
          if (distToNew < tolerance) {
            clusterAssignments[i][c] = 0;
            break;
          }
        }
      }
    }

    for (int c = 0; c < k; c++) {
      for (int i = 0; i < points.length; i++) {
        if (clusterAssignments[i][c] == 1) {
          for (int d = 0; d < points[i].length; d++) {
            if (points[i][d] > centroids[c][d]) {
