    double sum = 0;
    for (int i = 0; i < p.length; i++) {
      sum += pow(p[i] - c[i], 2);
    }
    return sqrt(sum);
  }

  for (int iter = 0; iter < maxIterations; iter++) {

    final clusters = <List<int>>[];

    for (int i = 0; i < points.length; i++) {
      double minDist = double.infinity;
      int bestCluster = -1;

      for (int j = 0; j < numClusters; j++) {
        double dist = clusterCentroid(points[i], centroids[j]);
        if (dist < minDist) {
          minDist = dist;
          bestCluster = j;
        }
      }

      if (bestCluster == -1) {
        bestCluster = rand.nextInt(numClusters);
      }

      clusters.add([i, bestCluster]);
    }


    final valid = <int>[];

    for (final cluster in clusters) {
      if (cluster.length >= 2) {
        valid.add(cluster[0]);
      }
    }

    if (valid.isEmpty) {
      break;
    }

    final newCentroids = <List<double>>[];
    for (int j = 0; j < numClusters; j++) {
      final pointsInCluster = <double>[];
      for (final idx in valid) {
        pointsInCluster.add(points[idx][j]);
      }
      newCentroids.add(pointsInCluster.isEmpty
          ? List.filled(centroids[j].length, 0)
          : pointsInCluster.reduce((a, b) => [a[0] + b[0], a[1] + b[1]]);
    }

    if (newCentroids == centroids) {
      break;
    }

    centroids = List.from(newCentroids);

    for (int i = 0; i < points.length; i++) {
      final minDist = <int>[];

      for (int j = 0; j < numClusters; j++) {
        if (valid.contains(j)) {
          minDist.add(clusterCentroid(points[i], centroids[j]));
        }
      }

      if (minDist.length == 1) {
        assignments[i] = minDist[0];
      }
    }
  }

  print('Cluster ${assignments[0]} centroid: ${centroids[0]}');
  print('Cluster ${assignments[1]} centroid: ${centroids[1]}');
  print('Cluster ${assignments[2]} centroid: ${centroids[2]}');

  print('  Points: ${points.map((p) => '${assignments[p.length - 1]} => $p').toList()}');
  print('Converged in $iter iteration(s).');
}

