        isNoise = false;
        clusterLabel[idx][i] = 1;
        for (int j = 0; j < k; j++) {
          if (clusterLabel[idx][j] == 1) {
            regions[idx][j] = 1;
          }
        }
        break;
      }
    }
    if (isNoise) {
      clusterLabel[idx][0] = -1;
    }

    List<int> seed = [idx];

    while (seed.isNotEmpty) {
      int point = seed.removeAt(0);
      bool isCluster = true;

      for (int i = 0; i < k; i++) {
        if (clusterLabel[point][i] == 1) {
          continue;
        }
        double d = (points[point][0] - centroids[i][0]).abs() + (points[point][1] - centroids[i][1]).abs();
        if (d <= eps) {
          isCluster = false;
          break;
        }
      }
      if (isCluster) {
        for (int i = 0; i < k; i++) {
          if (clusterLabel[point][i] != 1) {
            if (clusterLabel[point][i] == -1) {
              seed.add(point);
            } else {
              regions[point][i] = 1;
            }
          }
        }

        for (int i = 0; i < k; i++) {
          if (clusterLabel[point][i] == 1) {
            for (int j = 0; j < k; j++) {
              if (clusterLabel[point][j] == 1 && regions[point][j] == 0) {
                regions[point][j] = 1;
              }
            }
          }
        }
      }
    }
  }

  for (int i = 0; i < points.length; i++) {
    List<int> labelCount = List.filled(k, 0);
    for (int j = 0; j < k; j++) {
      if (clusterLabel[i][j] == 1) {
        labelCount[j]++;
      }
    }

    int bestIdx = 0;
    for (int j = 1; j < k; j++) {
      if (labelCount[j] > labelCount[bestIdx]) {
        bestIdx = j;
      }
    }

    clusterLabel[i][bestIdx] = 1;
    for (int j = 0; j < k; j++) {
      if (j != bestIdx) {
        clusterLabel[i][j] = 0;
      }
    }
  }

  List<List<int>> clusters = [];
  for (int i = 0; i < k; i++) {
    if (clusterLabel[i][0] == 1) {
      clusters.add(List.from(points) .. add(i));
    }
  }

  print('Converged in $numOfIterations iteration(s).');

  for (int i = 0; i < clusters.length; i++) {
    print('Cluster $i:');
    print('  Points: ${clusters[i]}');
    print(' centroid: ${clusters[i][0]},${clusters[i][1]}');
  }
}

