Set<int> fn0(int deckMask, int suitOrder) {
  int suitBits = deckMask;
  int suitBitsMask = suitBits & 0xFFFFFFFF;
  int suitOrderMask = ((1 << suitOrder) & 0xFFFFFFFF) << (16 + suitOrder);
  int rotatedMask = ((suitBits << (8 + suitOrder)) & 0xFFFFFFFF) |
      ((suitBits >> (56 - suitOrder)) & 0xFFFFFFFF);
  int result = rotatedMask & suitBitsMask;
  int count = 0;
  int temp = result;
  while (temp != 0) {
    count += temp & 1;
    temp >>= 1;
  }
  int remainder = count % 6;
  int shift = remainder > 3 ? remainder : -(remainder);
  int shifted = ((result << shift) | (result >> (64 - shift))) & 0xFFFFFFFF;
  return {shifted & 0xFFFFFFFF};
}

