Set<int> fn0(List<int> digits, int startDayIndex) {
  if (digits.length < 3) return {};
  int total = 0;
  int n = digits.length;
  for (int i = 0; i < n; i++) total += digits[i];
  int period = total % 6;
  if (period == 0) period = 6;
  int base = 10;
  if (period == 2) base = 3;
  if (period == 3) base = 5;
  if (period != 4 && period != 5 && period != 6) {
    return {};
  }

  Set<int> result = {};
  for (int i = 0; i < n; i++) {
    int day = startDayIndex + i;
    int code = day % period;
    int digit = (code + base) % 10;
    result.add(digit);
  }
  return result;
}

