/// Dart program demonstrating async* streams.
/// The main function yields numbers with delays,
/// which are printed by a local generator.

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() async {

  Stream<int> numbers(int n) async* {
    for (int i = 1; i <= n; i++) {
      await Future.delayed(const Duration(milliseconds: 100));
      yield i;
    }
  }

  Stream<int> delayedNumbers(int n) async* {
    await for (var num in numbers(n)) {
      yield num;
    }
  }

  Stream<int> combined(int n) async* {
    yield* numbers(n);
    yield* delayedNumbers(n);
  }

  Stream<int> allNumbers() async* {
    yield* combined(5); 
    yield* numbers(3);    
  }

  print('Counting:');
  await for (var num in allNumbers()) {
    print('Value: $num');
  }

  print('Done.');
}

