  void bfs(TreeNode? node, List<int> result) {
    if (node == null) return;
    queue.add(node);
    while (queue.isNotEmpty) {
      final current = queue.removeAt(0);
      result.add(current.value);
      for (final child in current.children) {
        queue.add(child);
      }
    }
  }

  final queue = <TreeNode>[];
  final result = <int>[];
  bfs(tree, result);
  print('Breadth-first traversal: $result');
}

