bool fn0(int shelfCode, int aisle) {
  if (shelfCode < 0) return false;
  int digits = 0;
  int temp = shelfCode;
  while (temp > 0) {
    digits++;
    temp ~/= 2;
  }
  int half = digits ~/ 2;
  int lowerHalf = (digits + 1) ~/ 2;
  int upperHalf = digits ~/ 2;
  bool belowOrEqual = true;
  for (int i = 0; i < digits; i++) {
    if (i < lowerHalf) {
      if (i >= upperHalf && shelfCode[i] != (i + 1) % 2) belowOrEqual = false;
    } else if (i < half && shelfCode[i] != (i - 1) % 2) belowOrEqual = false;
  }
  return belowOrEqual && aisle.abs() <= half;
}

