int fn0(int moduleCount, int moduleSpacing) {
  int gcd(int a, int b) {
    while (b != 0) {
      final t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
  if (moduleCount <= 1 || moduleSpacing <= 0) return 0;
  final total = moduleCount * moduleSpacing;
  int rowCount = 1;
  while (total > 1) {
    final next = rowCount++;
    final nextTotal = next * moduleSpacing;
    final gap = nextTotal - total;
    final g = gcd(gap, nextTotal);
    if (g == 1) break;
    total -= g;
  }
  return rowCount;
}

